/* Standalone mirror of the vulnerable loop in format_expand1 (format.c).
 * Confirms the heap-buffer-overflow trigger for an input ending in '#'. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

int main(int argc, char **argv)
{
    /* Simulate the fuzzer: null-terminate a 1-byte input "#" on the heap. */
    size_t size = 1;
    char *buf = (char *)malloc(size + 1);
    memcpy(buf, "#", size);
    buf[size] = '\0';

    const char *fmt = buf;
    char outbuf[64];
    size_t off = 0;
    int ch;

    /* Vulnerable loop from format.c format_expand1 */
    while (*fmt != '\0') {
        if (*fmt != '#') {
            outbuf[off++] = *fmt++;
            continue;
        }
        if (*fmt++ == '\0')   /* line 5466: checks current '#' byte, advances ptr */
            break;
        ch = (uint8_t)*fmt++; /* line 5469: consumes terminator, advances past end */
        /* default case: write '#' and ch */
        outbuf[off++] = '#';
        outbuf[off++] = (char)ch;
    }
    outbuf[off] = '\0';
    free(buf);
    return 0;
}
EOF
